  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.job-progress__status {
  flex: none;
  padding: 1px 8px;
  border-radius: 999px;
  font-size: 11px;
  line-height: 1.6;
  background: var(--muted, #f3f4f6);
  color: var(--muted-foreground, #6b7280);
}

.job-progress__item[data-phase="completed"] .job-progress__status {
  background: rgba(16, 185, 129, 0.14);
  color: #047857;
}

.job-progress__item[data-phase="failed"] .job-progress__status {
  background: rgba(239, 68, 68, 0.14);
  color: #b91c1c;
}

.job-progress__meter {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--muted, #f3f4f6);
}

.job-progress__meter-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--primary, #3b82f6);
  transition: width 200ms ease;
}

.job-progress__meter-fill[data-phase="completed"] {
  background: #10b981;
}

.job-progress__meter-fill[data-phase="failed"] {
  background: #ef4444;
}

.job-progress__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: var(--muted-foreground, #6b7280);
}

.job-progress__job-id {
  overflow-wrap: anywhere;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.job-progress__error {
  font-size: 12px;
}

.job-progress__error-summary {
  cursor: pointer;
  font-weight: 500;
  color: #b91c1c;
}

.job-progress__error-body {
  margin-top: 6px;
  padding: 8px;
  border-radius: 8px;
  background: rgba(239, 68, 68, 0.08);
}

.job-progress__error-message {
  margin: 0 0 4px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.job-progress__error-code {
  margin: 0;
  overflow-wrap: anywhere;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  color: var(--muted-foreground, #6b7280);
}

.job-progress__error-missing {
  margin: 0;
  font-size: 12px;
  color: #b91c1c;
}
"}]}

